--- index.html
+++ index.html
@@ -29,4 +29,75 @@
 </aside>
 </main><p class="footer">A pocket-sized field adventure · listen for the evening crickets ✦</p>
 </div>
 <script>
+const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
+ctx.imageSmoothingEnabled=false;
+const W=640,H=400,T=32;
+const species=[
+ {name:'Emberling',kind:'Jumping spider',type:'SUN',color:'#e88961',dark:'#8f4c42',hp:30,max:30,atk:8,desc:'A curious little jumper with a warm heart.',icon:'🕷'},
+ {name:'Fernweaver',kind:'Orb-weaver',type:'LEAF',color:'#8db56b',dark:'#4e7651',hp:27,max:27,atk:7,desc:'Spins dewdrop webs between the fern fronds.',icon:'🕷'},
+ {name:'Pebblepaws',kind:'Wolf spider',type:'EARTH',color:'#bb9871',dark:'#735844',hp:34,max:34,atk:9,desc:'A speedy ground scout with velvet paws.',icon:'🕷'},
+ {name:'Moonspinner',kind:'Garden spider',type:'MOON',color:'#9c9ad0',dark:'#595b8d',hp:26,max:26,atk:8,desc:'Its silvery silk glimmers after sunset.',icon:'🕷'},
+ {name:'Mossmop',kind:'Tarantula',type:'MOSS',color:'#b97c68',dark:'#71473f',hp:39,max:39,atk:10,desc:'A fluffy, gentle giant who loves moss.',icon:'🕷'},
+ {name:'Prismite',kind:'Peacock spider',type:'SUN',color:'#6db9ad',dark:'#3c7272',hp:25,max:25,atk:11,desc:'A tiny dancer with a jewel-bright fan.',icon:'🕷'}
+];
+let party=[{...species[0],hp:30,level:3}],state='intro',dialogIndex=0,steps=0,encounter=null,menuPage=0,music=true,audioCtx=null,beatTimer=null,moveHeld=null,moveTick=0,shake=0;
+let player={x:296,y:245,dir:'down',walk:0};
+let msg=['Welcome, little wanderer!','Mosslight Reserve is home to all kinds of spiders.','Explore the fernway and make a few friends.'];
+const keys={};
+const rand=(n)=>Math.floor(Math.random()*n);
+function rect(x,y,w,h,c){ctx.fillStyle=c;ctx.fillRect(Math.round(x),Math.round(y),Math.round(w),Math.round(h))}
+function text(s,x,y,size=12,color='#fff9dc',font='bold'){ctx.font=`${font} ${size}px "DM Mono", monospace`;ctx.fillStyle=color;ctx.fillText(s,x,y)}
+function panel(x,y,w,h,fill='#fff8dc',stroke='#465940'){rect(x+3,y+3,w,h,'#26392c');rect(x,y,w,h,stroke);rect(x+2,y+2,w-4,h-4,fill)}
+function roundedBar(x,y,w,h,pct,color){rect(x,y,w,h,'#cbcdb5');rect(x,y,Math.max(0,w*Math.max(0,pct)),h,color)}
+function shade(c,a){return c}
+function drawGrassTile(x,y,seed=0){rect(x,y,T,T,'#82a966');rect(x,y+21,T,11,'#779c60');rect(x+((seed*13)%22),y+((seed*7)%21),3,3,'#9abd72');rect(x+((seed*9+17)%28),y+((seed*11+4)%23),2,2,'#6e965d');
+ for(let j=0;j<3;j++){let xx=x+5+((seed*7+j*11)%23), yy=y+17+((seed*3+j*5)%11);rect(xx,yy,2,7,'#527c50');rect(xx-2,yy-3,3,4,'#628b53');rect(xx+2,yy-5,3,5,'#719656')}
+}
+function drawPath(x,y,seed){rect(x,y,T,T,'#d7bd85');rect(x,y+26,T,6,'#cfb37a');for(let i=0;i<5;i++){let px=x+((seed*11+i*17)%29),py=y+((seed*7+i*13)%26);rect(px,py,2,2,i%2?'#bca26e':'#e5cb91')}}
+function tree(x,y,scale=1){let s=scale;rect(x-9*s,y+18*s,35*s,7*s,'#63865a');rect(x-5*s,y+6*s,25*s,24*s,'#52794e');rect(x-9*s,y,23*s,19*s,'#658c55');rect(x+4*s,y-7*s,18*s,18*s,'#72965b');rect(x+2*s,y+6*s,5*s,4*s,'#84a964');rect(x-3*s,y+13*s,4*s,4*s,'#456d48');rect(x+8*s,y+2*s,4*s,4*s,'#85a862');rect(x+7*s,y+24*s,8*s,8*s,'#795b43');rect(x+10*s,y+24*s,3*s,5*s,'#96734b')}
+function flower(x,y,c){rect(x,y+3,2,6,'#587e4d');rect(x-2,y,2,2,c);rect(x+2,y,2,2,c);rect(x,y-2,2,2,c);rect(x,y+2,2,2,'#e6cc6d')}
+function drawWorld(){
+ rect(0,0,W,H,'#85a96a');
+ // meadow base with a soft checker of mossy patches
+ for(let y=0;y<400;y+=32)for(let x=0;x<640;x+=32){let q=((x/32*7+y/32*11)%9);if(q===2||q===5){rect(x+4,y+11,10,5,'#7fa363');rect(x+7,y+9,4,2,'#91b377')}if(q===1)rect(x+23,y+5,3,3,'#99b873')}
+ // winding sandy trail
+ [[192,0],[192,32],[192,64],[224,96],[224,128],[256,160],[256,192],[288,224],[288,256],[320,288],[320,320],[320,352]].forEach((p,i)=>drawPath(p[0],p[1],i+3));
+ // grass clearings
+ for(let y=64;y<352;y+=32){for(let x=32;x<160;x+=32)drawGrassTile(x,y,x+y);for(let x=384;x<608;x+=32)if((x+y)%3!==0)drawGrassTile(x,y,x+y)}
+ for(let y=0;y<64;y+=32)for(let x=320;x<608;x+=32)drawGrassTile(x,y,x+y);
+ // pond
+ rect(414,172,140,64,'#538d91');rect(422,168,121,7,'#7aa99a');rect(424,181,99,4,'#72a5a0');rect(444,202,26,3,'#a4c4a0');rect(494,217,18,3,'#85b5a8');
+ // shrubs / trees as canopy silhouettes
+ [[-2,-10,1.35],[61,-13,1.25],[128,-8,1.3],[275,-18,1.5],[365,-13,1.35],[474,-19,1.35],[579,-12,1.5],[0,92,1.3],[567,91,1.35],[12,193,1.25],[580,273,1.4],[67,345,1.5],[172,349,1.3],[416,347,1.35],[542,347,1.55]].forEach(a=>tree(...a));
+ // little fern tufts
+ for(let i=0;i<20;i++){let x=(i*83+39)%620,y=(i*61+23)%360;if(x>185&&x<350)continue;if(y>165&&y<243&&x>400&&x<560)continue;rect(x,y,2,8,'#557e4e');rect(x-4,y+2,4,3,'#638d54');rect(x+2,y-2,4,3,'#699256')}
+ [[105,57,'#f1d57d'],[168,108,'#eac3b0'],[376,72,'#eac7a9'],[366,305,'#f0d47a'],[104,285,'#e2afbd'],[457,250,'#f1d57d'],[572,156,'#e6bf9a'],[343,94,'#e8c1ad']].forEach(a=>flower(...a));
+ // web between trees
+ ctx.strokeStyle='#d9e3bd';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(132,58);ctx.lineTo(157,80);ctx.lineTo(185,58);ctx.moveTo(157,80);ctx.lineTo(157,48);ctx.moveTo(145,68);ctx.lineTo(170,68);ctx.stroke();
+ // trail sign
+ rect(351,129,4,24,'#795a3c');rect(342,125,24,12,'#efe0b3');rect(344,127,20,2,'#806748');text('FERN',345,134,6,'#577150');
+ drawPlayer();
+ // zone label
+ panel(12,12,120,23,'#f6efdb','#55674b');text('Mosslight · Fernway',20,27,9,'#44563d');
+ if(state==='intro')drawDialog('');
+ if(state==='dialog')drawDialog();
+ if(state==='menu')drawMenu();
+}
+function drawPlayer(){let x=Math.round(player.x),y=Math.round(player.y), bob=(player.walk%2?1:0);rect(x-8,y+12,18,5,'#607e52');rect(x-6,y-2+bob,14,16,'#d88d68');rect(x-5,y-7+bob,12,11,'#f1c89b');rect(x-6,y-9+bob,14,5,'#4d5946');rect(x-6,y-5+bob,3,4,'#4d5946');rect(x+5,y-5+bob,3,4,'#4d5946');rect(x-3,y-3+bob,2,2,'#28382d');rect(x+3,y-3+bob,2,2,'#28382d');rect(x-6,y+5+bob,12,3,'#557957');rect(x-5,y+9+bob,5,5,'#e9dfba');rect(x+2,y+9+bob,5,5,'#e9dfba');if(player.dir==='up'){rect(x-5,y-6+bob,12,6,'#4d5946')}}
+function drawSpider(sp,x,y,scale=1,face='left',frame=0){
+ let c=sp.color,d=sp.dark,s=scale;
+ // shadow
+ rect(x-24*s,y+17*s,49*s,5*s,'#425c3b66');
+ // legs with slight animated sway
+ ctx.strokeStyle=d;ctx.lineWidth=Math.max(2,3*s);ctx.lineCap='square';
+ for(let i=0;i<4;i++){let yy=y-9*s+i*6*s, ext=(i===0||i===3?17:21)*s, wig=(frame%2?2:-1)*s;ctx.beginPath();ctx.moveTo(x-12*s,yy);ctx.lineTo(x-ext,yy-9*s+wig);ctx.lineTo(x-(ext+5*s),yy-4*s+wig);ctx.moveTo(x+12*s,yy);ctx.lineTo(x+ext,yy-9*s-wig);ctx.lineTo(x+(ext+5*s),yy-4*s-wig);ctx.stroke()}
+ // body and abdomen
+ ctx.fillStyle=d;ctx.beginPath();ctx.ellipse(x,y+1*s,15*s,12*s,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.ellipse(x+(face==='left'?7:-7)*s,y+1*s,10*s,9*s,0,0,Math.PI*2);ctx.fill();ctx.fillStyle=c;ctx.beginPath();ctx.arc(x+(face==='left'?-10:10)*s,y-5*s,9*s,0,Math.PI*2);ctx.fill();
+ // face and markings
+ rect(x+(face==='left'?-13:9)*s,y-7*s,3*s,3*s,'#fff2d5');rect(x+(face==='left'?-12:10)*s,y-7*s,1.5*s,2*s,'#27352d');
+ if(sp.name==='Emberling'){rect(x-5*s,y-6*s,3*s,3*s,'#f6cf73');rect(x-3*s,y+1*s,9*s,2*s,'#f3c477')}
+ if(sp.name==='Fernweaver'){rect(x-5*s,y-4*s,8*s,3*s,'#d7e08f');rect(x-7*s,y+2*s,12*s,2*s,'#c7d782')}
+ if(sp.name==='Moonspinner'){rect(x-4*s,y-7*s,2*s,2*s,'#f2e5ad');rect(x-7*s,y+1*s,12*s,2*s,'#e3dbef')}
+ if(sp.name==='Prismite'){rect(x-3*s,y-8*s,7*s,4*s,'#df8bca');rect(x-3*s,y-7*s,2*s,2*s,'#f3cc77')}
+}

