function drawBattle(){
 let t=Date.now()/1000;
 let night=(Math.sin(t*.12)+1)*.5;
 rect(0,0,W,H,'#bed1bd');rect(0,0,W,185,'#c9ddca');rect(0,150,W,85,'#a9c79e');rect(0,228,W,92,'#809d6c');
 // distant hills and firefly flecks
 ctx.fillStyle='#92b88c';ctx.beginPath();ctx.moveTo(0,180);ctx.quadraticCurveTo(120,105,230,177);ctx.quadraticCurveTo(350,112,470,176);ctx.quadraticCurveTo(560,125,640,164);ctx.lineTo(640,245);ctx.lineTo(0,245);ctx.fill();
 for(let i=0;i<11;i++){let x=(i*67+25)%635,y=(i*43+17)%167;rect(x,y,2,2,i%2?'#f8edbd':'#f6f2d8')}
 // battle platforms
 ctx.fillStyle='#66845d';ctx.beginPath();ctx.ellipse(476,187,86,19,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#91ad72';ctx.beginPath();ctx.ellipse(474,182,79,14,0,0,Math.PI*2);ctx.fill();
 ctx.fillStyle='#66845d';ctx.beginPath();ctx.ellipse(167,300,103,23,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#9bb77c';ctx.beginPath();ctx.ellipse(167,294,96,17,0,0,Math.PI*2);ctx.fill();
 let foe=encounter?.sp||species[1],hero=party[0];
 drawSpider(foe,469,142,1.35,'left',Math.floor(t*4));drawSpider(hero,161,256,1.55,'right',Math.floor(t*4));
 panel(20,25,229,67,'#fff9e4','#4d6148');text(foe.name,34,47,14,'#293b30');text(`${foe.kind}  ·  Lv ${foe.level||2}`,34,63,9,'#7c8068','normal');text('HP',34,81,8,'#647158');roundedBar(58,73,163,9,foe.hp/foe.max,'#83ae68');text(`${Math.max(0,foe.hp)}/${foe.max}`,190,65,8,'#7d846f','normal');
 panel(374,211,243,79,'#fff9e4','#4d6148');text(hero.name,389,234,14,'#293b30');text(`${hero.kind}  ·  Lv ${hero.level||3}`,389,250,9,'#7c8068','normal');text('HP',389,268,8,'#647158');roundedBar(414,260,170,9,hero.hp/hero.max,'#83ae68');text(`${Math.max(0,hero.hp)}/${hero.max}`,551,253,8,'#7d846f','normal');
 drawDialog();
 if(state==='battleMenu')drawBattleMenu();
}
function wrapText(str,max=53){let words=str.split(' '),lines=[],line='';for(const word of words){if((line+' '+word).trim().length>max){lines.push(line);line=word}else line=(line+' '+word).trim()}if(line)lines.push(line);return lines}
function drawDialog(custom){
 panel(14,310,612,78,'#fff8df','#3c523d');
 let line=custom||currentMessage||'';let lines=wrapText(line,75);lines.slice(0,2).forEach((l,i)=>text(l,31,338+i*18,13,'#344437','normal'));
 if(state==='intro'||state==='dialog'||state==='battle'||state==='battleMenu'){
  rect(599,367,8,7,'#d47d62');rect(601,365,4,2,'#d47d62');
 }
}
function drawBattleMenu(){
 panel(389,306,237,80,'#f7f1dc','#526449');
 if(menuPage===0){text('What will you do?',402,326,10,'#586b51','bold');[['A','Skitter strike'],['B','Silk snare'],['C','Catch orb'],['D','Run away']].forEach((it,i)=>{let x=402+(i%2)*111,y=345+Math.floor(i/2)*26;text((selected===i?'▶ ':'  ')+it[0]+' '+it[1],x,y,9,selected===i?'#dd785d':'#3e5040','bold')})}
 else {text('Choose a companion',402,326,10,'#586b51','bold');party.slice(0,4).forEach((p,i)=>{let x=402+(i%2)*111,y=346+Math.floor(i/2)*24;text((selected===i?'▶ ':'  ')+p.name.slice(0,12),x,y,9,selected===i?'#dd785d':'#3e5040','bold')})}
}
function drawMenu(){drawWorld();rect(0,0,W,H,'#1a2c25aa');panel(120,52,400,286,'#f8f2de','#465c45');text('FIELD BAG',148,83,13,'#798164');text(menuPage===0?'Trail journal':'Pocket supplies',148,111,20,'#304333');
 if(menuPage===0){text('Mosslight Reserve  ·  Fernway',148,143,11,'#67755d','normal');text(`Steps wandered: ${steps}`,148,169,11,'#67755d','normal');text(`Companions: ${party.length} / 6`,148,190,11,'#67755d','normal');text('Caught spiders are added to your field party.',148,222,10,'#82866e','normal');text('ARROWS / WASD  move',148,255,10,'#475842');text('A / ENTER       choose · advance',148,273,10,'#475842');text('B / ESC         close bag',148,291,10,'#475842');}
 else {text('Cocoon orb',148,146,12,'#475842');text(`A soft, silken sphere for befriending wild spiders. × ${inventory.orbs}`,148,166,10,'#78816a','normal');text('Sweet berry',148,202,12,'#475842');text(`Restores 12 vitality to your lead friend. × ${inventory.berries}`,148,222,10,'#78816a','normal');text('Press A to use a berry · B to return',148,269,10,'#475842');}
 text('PAGE 1 / 2',441,315,8,'#969778');
}

