function drawSpider(sp,x,y,scale=1,face='left',frame=0){
 const c=sp.color,d=sp.dark,s=scale,dir=face==='left'?-1:1,shape=sp.shape||'wolf',mark=sp.mark||'#e9d59a';
 rect(x-31*s,y+19*s,63*s,6*s,'#26352677');
 // Deliberately varied silhouettes: spines, heavy armor, long widow legs, and a threat fan.
 ctx.strokeStyle=d;ctx.lineWidth=Math.max(2,(shape==='tarantula'?4:shape==='widow'?2:3)*s);ctx.lineCap='square';
 for(let i=0;i<4;i++){
  let yy=y-10*s+i*7*s,wig=(frame%2?2:-1)*s;
  let span=(shape==='widow'?27:shape==='tarantula'?18:shape==='jumper'?16:22)*s;
  let kneeY=yy-(i<2?11:8)*s+wig;
  ctx.beginPath();ctx.moveTo(x-10*s,yy);ctx.lineTo(x-span,kneeY);ctx.lineTo(x-(span+7*s),kneeY-5*s);
  ctx.moveTo(x+10*s,yy);ctx.lineTo(x+span,kneeY);ctx.lineTo(x+(span+7*s),kneeY-5*s);ctx.stroke();
