 }
 // Distinct abdomen proportions and posture.
 ctx.fillStyle=d;ctx.beginPath();
 if(shape==='tarantula')ctx.ellipse(x+dir*7*s,y+2*s,20*s,16*s,0,0,Math.PI*2);
 else if(shape==='widow')ctx.ellipse(x+dir*10*s,y+3*s,13*s,18*s,dir*.15,0,Math.PI*2);
 else if(shape==='orb')ctx.ellipse(x+dir*10*s,y+1*s,20*s,13*s,dir*.12,0,Math.PI*2);
